import math
body = doc.getObject('Body')
shape = body.Shape

def is_left_bore(f):
    try:
        s = f.Surface
        return s.__class__.__name__ == 'Cylinder' and abs(s.Radius - 20.0) < 1e-3 and abs(s.Center.x - (-50.0)) < 1e-3
    except Exception:
        return False

def is_left_outer(f):
    try:
        s = f.Surface
        return s.__class__.__name__ == 'Cylinder' and abs(s.Radius - 25.0) < 1e-3 and abs(s.Center.x - (-50.0)) < 1e-3
    except Exception:
        return False

def is_top_or_bottom(f):
    try:
        s = f.Surface
        if s.__class__.__name__ != 'Plane':
            return False
        n = s.Axis
        return abs(abs(n.z) - 1.0) < 1e-6
    except Exception:
        return False

def is_pure_front_or_rear(f):
    try:
        s = f.Surface
        if s.__class__.__name__ != 'Plane':
            return False
        n = s.Axis
        if abs(abs(n.y) - 1.0) < 1e-6:
            bb = f.BoundBox
            if (abs(bb.YMin) < 1e-3 and abs(bb.YMax) < 1e-3) or (abs(bb.YMin-100)<1e-3 and abs(bb.YMax-100)<1e-3):
                return True
        return False
    except Exception:
        return False

def is_left_opening(f):
    bb = f.BoundBox
    if bb.XMax > -25:
        return False
    if is_left_bore(f) or is_left_outer(f) or is_top_or_bottom(f) or is_pure_front_or_rear(f):
        return False
    return True

def concavity_sign(e):
    midp = (e.FirstParameter + e.LastParameter)/2.0
    P = e.valueAt(midp)
    T = e.tangentAt(midp)
    T.normalize()
    adj = []
    for f in shape.Faces:
        for fe in f.Edges:
            if fe.isPartner(e):
                adj.append(f)
                break
    if len(adj) != 2:
        return None
    f1, f2 = adj
    u1,v1 = f1.Surface.parameter(P)
    n1 = f1.normalAt(u1,v1)
    u2,v2 = f2.Surface.parameter(P)
    n2 = f2.normalAt(u2,v2)
    return n1.cross(n2).dot(T)

